# Generated by build.py from recipe.yml for recipe pop3-limit-a-mailbox-to-imap. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'example.com', '--mailbox', '"ann@example.com:annpass;protocols=imap"', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'shop@example.com:shoppass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/', 'pop3://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8080/shop.example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 1 FLAGS" imap://127.0.0.1:8081/INBOX
try { curl.exe -sS -u ann@example.com:annpass pop3://127.0.0.1:8082/ } finally { Stop-Process $server0 }
